import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n, m = data[0], data[1]
    if m < n:
        print(-1)
        return

    edges = []
    for index in range(2, len(data), 3):
        airport, factory, days = data[index:index + 3]
        edges.append((days, airport - 1, factory - 1))
    del data

    edges.sort()
    costs = []
    for days, _, _ in edges:
        if not costs or costs[-1] != days:
            costs.append(days)

    def feasible(limit):
        adjacency = [[] for _ in range(n)]
        for days, airport, factory in edges:
            if days > limit:
                break
            adjacency[airport].append(factory)

        if any(not neighbors for neighbors in adjacency):
            return False

        left_match = [-1] * n
        right_match = [-1] * n
        matched_count = 0
        infinity = n + 1

        while True:
            distance = [-1] * n
            queue = []
            for airport in range(n):
                if left_match[airport] == -1:
                    distance[airport] = 0
                    queue.append(airport)

            shortest = infinity
            for airport in queue:
                next_distance = distance[airport] + 1
                if next_distance > shortest:
                    continue

                for factory in adjacency[airport]:
                    partner = right_match[factory]
                    if partner == -1:
                        if next_distance < shortest:
                            shortest = next_distance
                    elif next_distance < shortest and distance[partner] == -1:
                        distance[partner] = next_distance
                        queue.append(partner)

            if shortest == infinity:
                return False

            cursor = [0] * n

            for root in range(n):
                if left_match[root] != -1 or distance[root] != 0:
                    continue

                stack = [root]
                path = []

                while stack:
                    airport = stack[-1]
                    neighbors = adjacency[airport]

                    if cursor[airport] == len(neighbors):
                        distance[airport] = -1
                        stack.pop()
                        if path:
                            path.pop()
                        continue

                    factory = neighbors[cursor[airport]]
                    cursor[airport] += 1
                    partner = right_match[factory]

                    if partner == -1:
                        if distance[airport] + 1 != shortest:
                            continue

                        path.append(factory)
                        for position, path_airport in enumerate(stack):
                            path_factory = path[position]
                            left_match[path_airport] = path_factory
                            right_match[path_factory] = path_airport

                        matched_count += 1
                        if matched_count == n:
                            return True
                        break

                    if (
                        distance[partner] == distance[airport] + 1
                        and distance[partner] < shortest
                    ):
                        stack.append(partner)
                        path.append(factory)

    if not feasible(costs[-1]):
        print(-1)
        return

    low = 0
    high = len(costs) - 1
    while low < high:
        middle = (low + high) // 2
        if feasible(costs[middle]):
            high = middle
        else:
            low = middle + 1

    print(costs[low])


if __name__ == "__main__":
    main()
